import React, { useState } from "react";
import styled from "styled-components";
import FastaTable from "./Fasta";
import VirulenceTable from "./Virulence";
import AmrTable from "./Amr";

const Container = styled.div`
  width: 100%;
  padding: 20px;
  display: flex;
  justify-content: center;
  align-items: center;
`;

const Wrapper = styled.div`
  width: 80%;
  max-width: 1200px;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const Title = styled.h1`
  font-size: 36px;
  font-weight: bold;
  color: #333;
  margin-bottom: 20px;
  text-align: center;
`;

const ButtonGroup = styled.div`
  display: flex;
  justify-content: center;
  margin-bottom: 20px;
`;

const Button = styled.button`
  padding: 10px 20px;
  background-color: transparent;
  color: ${(props) => (props.selected ? "#007bff" : "#000")};
  border: 2px solid ${(props) => (props.selected ? "#007bff" : "#ccc")};
  border-radius: 5px;
  font-size: 25px;
  font-weight: ${(props) => (props.selected ? "bold" : "normal")};
  cursor: pointer;
  margin: 0 30px;
  &:last-child {
    margin-right: 0;
  }
`;

const Image = styled.img`
  width: 100%;
  height: auto;
  display: block;
`;

const ClickArea = styled.div`
  position: absolute;
  cursor: pointer;
  background: rgba(255, 0, 0, 0.15);
  border-radius: 5px;
`;

const ResultComponent = ({ fastaInfo, virulenceInfo, amrInfo }) => {
  const [selectedTab, setSelectedTab] = useState("Fasta");

  const handleTabClick = (tab) => {
    setSelectedTab(tab);
  };

  const handleClick = (part) => {
    alert(`Bạn đã chọn: ${part}`);
  };

  return (
    <Container>
      <Wrapper>
        <Title>Kết quả phân tích mẫu</Title>
        <ButtonGroup>
          <Button
            selected={selectedTab === "Fasta"}
            onClick={() => handleTabClick("Fasta")}
          >
            Fasta
          </Button>
          <Button
            selected={selectedTab === "Virulence"}
            onClick={() => handleTabClick("Virulence")}
          >
            Virulence
          </Button>
          <Button
            selected={selectedTab === "AMR"}
            onClick={() => handleTabClick("AMR")}
          >
            AMR
          </Button>
        </ButtonGroup>

        {selectedTab === "Fasta" && <FastaTable sample={fastaInfo} />}
        {selectedTab === "Virulence" && <VirulenceTable data={virulenceInfo} />}
        {selectedTab === "AMR" && <AmrTable data={amrInfo} />}

        <Image src="/Bacteria-Cell.jpg" alt="Bacteria" />
        <ClickArea style={{ top: "17%", left: "45%", width: "12%", height: "8%" }} onClick={() => handleClick("Nucleoid (DNA)")} />
      <ClickArea style={{ top: "23%", left: "18%", width: "12%", height: "6%" }} onClick={() => handleClick("Ribosomes")} />
      <ClickArea style={{ top: "12%", left: "40%", width: "10%", height: "6%" }} onClick={() => handleClick("Cytoplasm")} />
      <ClickArea style={{ top: "27%", left: "70%", width: "8%", height: "6%" }} onClick={() => handleClick("Plasmid")} />
      <ClickArea style={{ top: "18%", left: "77%", width: "8%", height: "5%" }} onClick={() => handleClick("Pili")} />
      <ClickArea style={{ top: "48%", left: "68%", width: "12%", height: "6%" }} onClick={() => handleClick("Inclusion Bodies")} />
      <ClickArea style={{ top: "63%", left: "78%", width: "15%", height: "8%" }} onClick={() => handleClick("Flagellum")} />
      <ClickArea style={{ top: "62%", left: "38%", width: "14%", height: "6%" }} onClick={() => handleClick("Cytoplasmic Membrane")} />
      <ClickArea style={{ top: "57%", left: "28%", width: "10%", height: "6%" }} onClick={() => handleClick("Cell Wall")} />
      <ClickArea style={{ top: "51%", left: "18%", width: "10%", height: "6%" }} onClick={() => handleClick("Capsule")} />

      </Wrapper>
    </Container>
  );
};

export default ResultComponent;
